def test_redos_vulnerability(pattern):
    try:
        # Test if the pattern is vulnerable to ReDoS
        re.compile(pattern)
        print("Pattern is safe (no ReDoS vulnerability detected).")
    except re.error:
        print("Pattern is unsafe (potential ReDoS vulnerability detected).")

# Example of a potentially ReDoS-prone pattern
test_redos_vulnerability(r'(a+)+b')

