import re
import time

def search_pattern(pattern: str, content: str) -> bool:
    try:
        # Add a time limit to prevent ReDoS attacks
        start_time = time.time()
        timeout = 5  # seconds

        # Use a timeout to limit regex execution time
        def timeout_handler():
            raise TimeoutError("Regex execution timed out")

        import signal
        signal.signal(signal.SIGALRM, timeout_handler)
        signal.alarm(timeout)

        match = re.search(pattern, content)
        signal.alarm(0)  # Cancel the alarm
        return bool(match)
    except re.error:
        return False
    except TimeoutError:
        return False
    except Exception:
        return False
